 {tab === 'Planning' && <><section className="panel"><div className="panel-title"><h2>Size the client-owned spare pool</h2>{onboard && <button className="primary" onClick={() => open('Save planning scenario', [{ name: 'pool', label: 'Compatibility pool', options: Array.from(new Set(data.equipment.filter(a => a.purpose === 'SUPPORTED').map(a => a.pool))).map(x => ({ value: x, label: x })) }, { name: 'configuration', label: 'Approved configuration', options: Array.from(new Set(data.equipment.filter(a => a.purpose === 'SUPPORTED').map(a => a.configuration))).map(x => ({ value: x, label: x })) }, { name: 'afr', label: 'Annual failure probability (0–1)', type: 'number', hint: '0.02 means 2%. Supply an attributable rate or an explicit assumption.' }, { name: 'days', label: 'Replenishment / repair exposure window (days)', type: 'number' }, { name: 'level', label: 'Target stock sufficiency probability (0–1)', type: 'number', value: .95 }, { name: 'contingency', label: 'Separate common-mode contingency reserve', type: 'number', value: 0 }, { name: 'source', label: 'Evidence citation / planning assumption' }, { name: 'notes', label: 'Applicability, uncertainty, redundancy & placement assumptions', type: 'textarea' }], 'plan')}>Model a scenario <Arrow /></button>}</div><p className="subtle">Installed population comes from your onboarded equipment. Failure demand uses attributable input, a stated exposure window, and an explicit target. Quantity planning and endpoint recovery-time coverage are separate decisions. This model assumes independent failures; contingency capacity is shown separately.</p></section>{data.plans.slice().reverse().map(p => { const available = data.equipment.filter(a => a.purpose === 'SPARE' && a.pool === p.pool && a.configuration === p.configuration && a.status === 'READY' && a.testDue && new Date(a.testDue) > new Date()).length; return <section className="panel" key={p.id}><div className="panel-title"><div><h2>{p.pool} · {p.configuration}</h2><p>{p.population} supported units · scenario saved {date(p.at)}</p></div><span className="badge">{p.result.method}</span></div><div className="metrics"><Metric label="EXPOSURE WINDOW DEMAND" value={p.result.demand.toFixed(2)} detail={`${(p.afr * 100).toFixed(2)}% annual failure input · ${p.days} days`}/><Metric label="MODELED SPARE QUANTITY" value={p.result.total} detail={`${p.result.ordinaryReserve} ordinary + ${p.contingency} contingency`}/><Metric label="CURRENT READY SPARES" value={available} detail="Compatible, verified & unreserved"/><Metric label="QUANTITY GAP" value={Math.max(0, p.result.total - available)} detail={`${(p.level * 100).toFixed(2)}% modeled sufficiency target`}/></div><p><strong>Evidence / assumption:</strong> {p.source}</p><p className="subtle">{p.notes}</p><p className="subtle">Snapshot preserves population and assumptions at calculation time. Stock quantity does not establish a delivery SLA; verify retrieval, transit, configuration, and installation against endpoint recovery targets.</p></section>; })}{!data.plans.length && <section className="panel"><Empty title="No planning scenarios" text="Onboard supported equipment, then model explicit failure and replenishment assumptions. No manufacturer failure rates are invented."/></section>}</>}
